using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Threading;using Renci.SshNet;using Renci.SshNet.Common;
namespace KlipperWinForms {using Obj=Dictionary<string,object>;
 static class SshOperations {
  internal static string Command(SshClient client,string command,bool allowError=false){using(var cmd=client.CreateCommand(command)){cmd.CommandTimeout=TimeSpan.FromSeconds(40);string result=cmd.Execute();if(cmd.ExitStatus!=0&&!allowError)throw new Exception("Linux 명령 실패: "+cmd.Error+result);return result.TrimEnd();}}
  internal static string Read(SftpClient s,string path){using(var m=new MemoryStream()){s.DownloadFile(path,m);return Encoding.UTF8.GetString(m.ToArray());}}
  internal static void Put(SftpClient s,string path,byte[] bytes){using(var m=new MemoryStream(bytes))s.UploadFile(m,path,true);s.ChangePermissions(path,600);}
  static string Parent(string p){int i=p.LastIndexOf('/');return i<=0?"/":p.Substring(0,i);}
  static Obj Identity(SshClient c,SftpClient s,string device){if(!device.StartsWith("/dev/")||device.IndexOfAny(new[]{'\n','\r','\0'})>=0)throw new Exception("Invalid serial device path");Command(c,"test -c "+U.Shell(device));string resolved=Command(c,"readlink -f -- "+U.Shell(device));string sys="/sys"+Command(c,"udevadm info --query=path --name="+U.Shell(device));string usb=sys;while(usb.StartsWith("/sys/")&&!s.Exists(usb+"/idVendor"))usb=Parent(usb);if(!usb.StartsWith("/sys/"))usb="";Func<string,string> read=n=>usb!=""&&s.Exists(usb+"/"+n)?Read(s,usb+"/"+n).Trim():"";return new Obj{{"device",device},{"realpath",resolved},{"sys_path",sys},{"usb_path",usb},{"serial",read("serial")},{"vid",read("idVendor")},{"pid",read("idProduct")},{"product",read("product")},{"manufacturer",read("manufacturer")},{"readable",Command(c,"test -r "+U.Shell(device)+" && echo yes",true)=="yes"},{"writable",Command(c,"test -w "+U.Shell(device)+" && echo yes",true)=="yes"}};}
  static List<Obj> Devices(SshClient c,SftpClient s){var entries=new Dictionary<string,Obj>();foreach(string dir in new[]{"/dev/serial/by-id","/dev/serial/by-path"}){if(!s.Exists(dir))continue;foreach(var file in s.ListDirectory(dir).Where(f=>f.IsSymbolicLink).OrderBy(f=>f.Name)){try{var info=Identity(c,s,file.FullName);string key=Json.S(info,"realpath");if(entries.ContainsKey(key)){var aliases=(object[])entries[key]["aliases"];entries[key]["aliases"]=aliases.Concat(new object[]{file.FullName}).ToArray();}else{info["aliases"]=new object[]{file.FullName};entries[key]=info;}}catch(SftpPathNotFoundException){}}}return entries.Values.ToList();}
  static void Same(Obj expected,Obj actual){foreach(string key in new[]{"usb_path","serial","vid","pid"})if(Json.S(expected,key)!=""&&Json.S(expected,key)!=Json.S(actual,key))throw new Exception("선택한 원격 보드가 변경되었습니다: "+key);if(Json.S(expected,"usb_path")==""&&Json.S(expected,"sys_path")!=Json.S(actual,"sys_path"))throw new Exception("원격 시리얼 장치 경로 변경");}
  // Katapult and the service runner use Python only on Linux. Windows has no
  // interpreter or Python engine. Guard values are injected into a private copy
  // of that existing program; its installed original is never modified.
  internal static string GuardScript(string upstream,Obj info,Obj selected,bool check=false) => SshKatapultGuard.Apply(upstream,info,selected,check);
  public static Obj Run(Obj req,string data,Action<string> log){string host=Json.S(req,"host").Trim(),user=Json.S(req,"username"),password=Json.S(req,"password");int port=req.ContainsKey("port")?Convert.ToInt32(req["port"]):22;if(host==""||user==""||port<1||port>65535)throw new Exception("IP, port and account are required");string hostId="["+host+"]:"+port,keyFile=Path.Combine(data,"ssh-hostkeys.json");var keys=File.Exists(keyFile)?U.Read(keyFile):new Obj();string accepted=Json.S(req,"accepted_fingerprint"),fp="";Obj challenge=null;bool changed=false;
   EventHandler<HostKeyEventArgs> trust=(sender,e)=>{using(var hash=System.Security.Cryptography.SHA256.Create())fp="SHA256:"+Convert.ToBase64String(hash.ComputeHash(e.HostKey)).TrimEnd('=');if(keys.ContainsKey(hostId)){e.CanTrust=Json.S(keys,hostId)==fp;changed=!e.CanTrust;}else{e.CanTrust=accepted==fp;if(!e.CanTrust)challenge=new Obj{{"host",hostId},{"type",e.HostKeyName},{"fingerprint",fp}};}};
   Func<ConnectionInfo> connection=()=>new ConnectionInfo(host,port,user,new PasswordAuthenticationMethod(user,password)){Timeout=TimeSpan.FromSeconds(15)};
   using(var ssh=new SshClient(connection())){ssh.HostKeyReceived+=trust;try{ssh.Connect();}catch{if(changed)throw new Exception("SSH 서버 키가 저장된 키와 다릅니다.");if(challenge!=null)return new Obj{{"host_key_required",challenge}};throw;}keys[hostId]=fp;U.Write(keyFile,keys);using(var sftp=new SftpClient(connection())){sftp.HostKeyReceived+=trust;sftp.Connect();string home=sftp.WorkingDirectory;
    if(Json.S(req,"action")=="ssh_connect"){string python=new[]{home+"/klippy-env/bin/python","/usr/bin/python3","/usr/local/bin/python3"}.FirstOrDefault(p=>sftp.Exists(p))??"/usr/bin/python3";string script=new[]{home+"/katapult/scripts/flashtool.py",home+"/Katapult/scripts/flashtool.py",home+"/CanBoot/scripts/flashtool.py"}.FirstOrDefault(p=>sftp.Exists(p))??home+"/katapult/scripts/flashtool.py";string version=Command(ssh,U.Shell(python)+" -c "+U.Shell("import sys,serial; print(sys.version.split()[0])"),true);return new Obj{{"hostname",Command(ssh,"hostname")},{"home",home},{"python",python},{"script",script},{"python_ready",Regex.IsMatch(version,@"^3\.\d+\.\d+")},{"python_error",version},{"script_exists",sftp.Exists(script)},{"devices",Devices(ssh,sftp).Cast<object>().Concat(Regex.IsMatch(version,@"^3\.\d+\.\d+")?SshRp2040Install.Scan(ssh,python).Concat(SshDfuUsb.Scan(ssh,python)).ToArray():new object[0]).ToArray()},{"fingerprint",fp},{"klipper_service",Command(ssh,"systemctl is-active klipper.service",true)}};}
    if(Json.S(req,"action")=="ssh_dfu_install")return SshDfuUsb.Run(ssh,sftp,req,data,log);
    if(Json.S(req,"action")=="ssh_rp2040_install")return SshRp2040Install.Run(ssh,sftp,req,data,log);
    var info=Safety.Inspect(Json.S(req,"firmware"));byte[] bin=File.ReadAllBytes(Json.S(req,"firmware"));if(U.Hash(bin)!=Json.S(info,"sha256")||Json.S(req,"sha256")!=Json.S(info,"sha256"))throw new Exception("BIN 변경 감지. 다시 선택하세요.");var selected=Json.D(req,"device");string device=Json.S(selected,"device");if(!new[]{"/dev/serial/by-id","/dev/serial/by-path"}.Contains(Parent(device)))throw new Exception("Select a by-id/by-path board");Same(selected,Identity(ssh,sftp,device));string scriptPath=Json.S(req,"script"),interpreter=Json.S(req,"python");string guarded=GuardScript(Read(sftp,scriptPath),info,selected,Json.S(req,"action")=="ssh_check");string temp=Command(ssh,"mktemp -d /tmp/klipper-native-cs-XXXXXXXXXXXX");if(!Regex.IsMatch(temp,@"^/tmp/klipper-native-cs-[A-Za-z0-9]+$"))throw new Exception("Unexpected staging directory");bool started=false,completed=false;
    try{Put(sftp,temp+"/klipper.bin",bin);Put(sftp,temp+"/flashtool.py",Encoding.UTF8.GetBytes(guarded));using(var read=new MemoryStream()){sftp.DownloadFile(temp+"/klipper.bin",read);if(U.Hash(read.ToArray())!=Json.S(info,"sha256"))throw new Exception("SFTP hash mismatch");}bool check=Json.S(req,"action")=="ssh_check";string service=Json.S(req,"service");if(service=="")service="klipper";if(!Regex.IsMatch(service,@"^[A-Za-z0-9_][A-Za-z0-9_.@-]*$"))throw new Exception("Invalid service name");string runner=SshServiceRunner.Script(temp,interpreter,device,service,check,Json.B(req,"stop_service"));Put(sftp,temp+"/runner.py",Encoding.UTF8.GetBytes(runner));started=true;string pid=SshServiceRunner.Start(ssh,interpreter,temp+"/runner.py",Json.B(req,"stop_service")?password:"");log("원격 작업 PID "+pid+" · "+temp+"/operation.log");DateTime end=DateTime.UtcNow.AddMinutes(10);int offset=0;var all=new MemoryStream();Action readLog=()=>{if(sftp.Exists(temp+"/operation.log")){using(var stream=sftp.OpenRead(temp+"/operation.log")){stream.Position=offset;byte[] buffer=new byte[65536];int n;while((n=stream.Read(buffer,0,buffer.Length))>0){all.Write(buffer,0,n);log(Encoding.UTF8.GetString(buffer,0,n));offset+=n;}}}};
     while(DateTime.UtcNow<end){readLog();if(sftp.Exists(temp+"/result.json")){readLog();var result=Json.Read(Read(sftp,temp+"/result.json"));completed=true;string text=Encoding.UTF8.GetString(all.ToArray());string logs=Path.Combine(data,"ssh-logs");Directory.CreateDirectory(logs);string logfile=Path.Combine(logs,Guid.NewGuid().ToString("N")+".log");File.WriteAllText(logfile,text,Encoding.UTF8);int exitCode=Convert.ToInt32(result["exit_code"]);if(exitCode!=0)throw new Exception((exitCode==90?"Klipper 서비스 중지 실패: SSH 로그인 비밀번호와 계정의 sudo 권한을 확인하세요. 펌웨어 작업은 시작하지 않았습니다.":exitCode==91?"Klipper 서비스 복구 실패: Linux에서 서비스 상태를 확인하세요.":exitCode==95?"보드의 Klipper 복귀 명령 확인 실패. 로그와 서비스 상태를 확인하세요.":"원격 Katapult 작업 실패 ("+exitCode+").")+" 로그: "+logfile);
       var m=Regex.Match(text,@"MCU type:\s*(\S+)");var a=Regex.Match(text,@"Application Start:\s*0x([0-9a-fA-F]+)");if(!m.Success||!a.Success)throw new Exception("원격 보드 정보가 없습니다.");var board=new Obj{{"mcu",m.Groups[1].Value},{"application_start",Convert.ToInt64(a.Groups[1].Value,16)}};Safety.Compatible(info,board);return new Obj{{"success",true},{"verified",!check},{"board",board},{"local_log",logfile},{"service_restarted",Json.B(result,"service_restarted")}};
      }Thread.Sleep(300);}throw new TimeoutException("Remote job timed out");
    }catch(Exception ex){if(started&&!completed)throw new Exception("원격 작업이 계속 실행 중일 수 있습니다. 재업로드하지 말고 로그를 확인하세요: "+temp+"/operation.log\n"+ex.Message,ex);throw;}finally{if(completed){foreach(string name in new[]{"klipper.bin","flashtool.py","runner.py","application-ready","result.json","operation.log"})try{sftp.DeleteFile(temp+"/"+name);}catch{}try{sftp.DeleteDirectory(temp);}catch{}}}
   }}
  }
 }
}
